/* DynamiteOrbit.ai — what is new on the screens, from one version to the next (demande de JP : « tague-moi ce qui est nouveau
   dans l'interface entre les versions pour faciliter la revue humaine… quand on passe à une nouvelle revue seulement cache
   les tags, sinon laisse-les actifs, pour la traçabilité et faciliter les checks croisés »).
   The tool changes fast ; the person who reviews it must find what changed without hunting for it. Every version that
   changes a screen declares its lines here : what is new, in a sentence, on which screen, and on WHICH ELEMENT of that screen.
   The element then carries a mark (core/whats_new_ui.js, installed once), and a panel lists the lines with « Montrer ».
   A REVIEW is what was published since its base version. Its marks STAY for as long as the review is open — a line can be
   ticked « vu », the mark remains, in another colour : the trace of what was checked. Only « Passer à une nouvelle revue »
   hides them : the base becomes the running version, and the next version brings its own marks. The review before is kept,
   and can be opened again.
   Pure, except for the review kept in the browser. A test holds that the running version has its lines. */

import { parseVersion, newer } from "./update_check.js";

/** The lines, newest first. sel : a CSS selector of the element that is new (the first one found on the screen is marked) ;
    where : the address of a screen that shows it (absent : it is in a menu, said in `how`) ; noMark : listed, but no mark on the screen
    (the logo and the wand of the top bar : JP, 23 novembre, « enlève-le svp »). */
export const NEWS = [
  { id: "sw-pack-old", v: "0.201.1", title: "Charge et équilibrage : un logiciel d'avant le dit", text: "Un projet qui garde le logiciel du BM d'avant le module simulé n'a pas la même simulation dans les deux fenêtres : « Charge et équilibrage » le dit dans un bandeau jaune et porte le bouton « Mettre à jour le logiciel du BM » (une étape annulable). Ensuite, l'état de charge de chaque CORE monte avec le profil, dans les deux fenêtres.", where: "#/swsim", sel: "[data-bal-stale]", how: "Logiciel › Essayer, « Charge et équilibrage », sur un projet BM enregistré avant le 26 novembre." },
  { id: "sw-pack", v: "0.201.0", title: "Logiciel : une seule simulation du module", text: "Le monitoring, « Charge et équilibrage » et le banc montrent le même module simulé : le profil joué le charge ou le décharge, il chauffe, et le logiciel lui répond — contacteur ouvert, courant dératé, pompe. La charge et la décharge sont écrites à partir des seuils du logiciel : chacun est franchi par la physique, au moins une fois. Le temps va jusqu'à ×400.", where: "#/swsim", sel: "[data-bal-shared]", how: "Charger « BM 8s8p - 21700 », Logiciel › Essayer : « Jouer le profil », puis ouvrir « Charge et équilibrage » et le monitoring." },
  { id: "sw-pack-txt", v: "0.201.0", title: "Profils : le module dans le fichier", text: "Un profil exporté en .txt porte aussi ce qui mène le module (module.mode, module.load, module.push, module.cv_fail, module.heat_to, module.ambient) et, en 5e champ, les seuils qu'un événement vise ; il se réimporte tel quel, et le prompt pour l'IA les nomme.", where: "#/swsim", sel: "[data-sw-profile-bank]", how: "Logiciel › Essayer : « Banque »." },
  { id: "mech-reqs", v: "0.200.0", title: "Mécanique et Électronique : 1 Exigences", text: "Une page Exigences en tête de la Mécanique et de l'Électronique, comme au Logiciel. Elle lit l'export .csv de DynamiteAgile tel quel, toutes ses colonnes gardées ; les besoins disent le pourquoi, les exigences sont groupées par catégorie, et chacune dit les disciplines qui la portent (M · E · L, en pointillé tant que la proposition de l'outil n'est pas confirmée). « Concevoir avec l'IA » copie la consigne ; « Vers DynamiteAgile » rend le fichier avec l'allocation remplie.", where: "#/mreq", sel: "[data-rq], .rq-studio", how: "Mécanique › 1 Exigences : « Exemple : le Rover »." },
  { id: "sw-nowire", v: "0.199.0", title: "Logiciel : le casse-tête sans fil", text: "Plus aucune ligne : chaque rangée finit sur une action, et ce qu'elle demande s'emboîte contre elle. La forme et la couleur de la clé disent ce que la prise porte (une décision 0 / 1, une grandeur, un état) : une pièce du mauvais type n'entrerait pas. Une pièce qui sert à plusieurs endroits est posée une fois, et ailleurs en jumeau pointillé ; son « ×n » ouvre le bloc d'interface : ce qu'elle prend, et chaque endroit où elle va.", where: "#/sw", sel: "[data-copies]", how: "Charger « BM 8s8p - 21700 », Logiciel › Conception, vue « Casse-tête » ; cliquer un « ×2 »." },
  { id: "pcba-layers", v: "0.199.0", title: "PCBA : de 2 à 12 couches", text: "Le nombre de couches d'une carte va de 2 à 12. Au choix, la masse va sur l'interne 1 et le plus gros rail sur la dernière interne ; l'empilage, les Gerber (.G1 à .G10), la vue et le routeur suivent.", where: "#/pcba", sel: ".pv-layers", how: "Électronique › PCBA, étape Implantation : « Couches »." },
  { id: "bm-bms3", v: "0.198.0", title: "BM : la carte du BMS central, 3 po × 3 po", text: "Une nouvelle carte dans le projet BM, 76,2 × 76,2 mm : elle vit sur le module ou sur le 12 V (le premier présent), collecte la chaîne RS-485 des 8 CORE, lit le courant sur le shunt de la barre de retour, commande le contacteur, la précharge et le pyrofusible, et parle au véhicule et à la borne en CAN FD isolé. Le routeur laisse 12 liaisons sur 274, et la carte le dit.", where: "#/pcba/BMS-CENTRAL-3X3", sel: ".role-switch", how: "Charger « BM 8s8p - 21700 », Électronique › PCBA : « BMS central 3 po × 3 po »." },
  { id: "sw-hw-gaps", v: "0.198.0", title: "Logiciel : les écarts entre la carte et le logiciel", text: "Le guide dit ce que la carte porte et que le logiciel ne commande pas encore (précharge, pyrofusible, réveil, tension du module), et ce que le logiciel commande et que la carte ne porte pas. Un net qui porte déjà une fonction n'est jamais proposé à une autre broche, ni dans l'essai sur la vraie carte, qui ne pique plus une valeur relue de la chaîne sur une broche.", where: "#/sw", sel: "[data-sw-fix-tour]", how: "Logiciel › Les blocs : le guide, ou « n à corriger »." },
  { id: "sw-refs", v: "0.197.0", title: "Logiciel : les Références", text: "Dernière tuile du groupe Logiciel : les sources que les écrans citent, par sujet (équilibrage, charge, architecture d'un BMS automobile, la cellule, les normes), chacune avec comment elle a été lue — lu, page lue, non lu —, ce qu'elle dit que l'outil utilise et les écrans qui la citent ; et ce qu'aucune source lue ne dit. Un numéro [n] sur un écran ouvre sa ligne.", where: "#/swref", sel: "[data-ref-topic]", how: "Logiciel › Références." },
  { id: "sw-balance-light", v: "0.197.0", title: "Logiciel : l'équilibrage se voit", text: "La fenêtre « Charge et équilibrage » se déplace par sa barre de titre ; une lumière verte dit quand l'équilibrage passif commence et combien de CORE se déchargent. Il tourne désormais PENDANT la charge, comme le prévoit un circuit de surveillance du commerce [1] ; ralentir la charge reste un réglage. Le monitoring montre la DEL de l'équilibrage et les 8 CORE qui montent vers 4,2 V.", where: "#/swsim", sel: "[data-sw-balance-open]", how: "Logiciel › Essayer : « Charge et équilibrage », puis « Monitoring du BM-SWAP »." },
  { id: "sw-bm-update-fix", v: "0.196.1", title: "Logiciel : l'écran des blocs revient", text: "Pour un projet BM enregistré avant la v0.193.0, l'écran des blocs restait vide : le bouton « Mettre à jour le logiciel du BM » plantait avant d'être dessiné. Il est de retour en tête du volet de gauche ; un clic prend le logiciel complet du BM (une étape annulable).", where: "#/sw", sel: "[data-sw-fix-tour]", how: "Logiciel › Les blocs, d'un projet BM enregistré avant le 24 novembre." },
  { id: "sw-balance", v: "0.196.0", title: "Logiciel : charge et équilibrage passif, en accéléré", text: "« Charge et équilibrage » ouvre les 8 CORE pendant une charge : partis déséquilibrés de 3,0 V (0 % = 2,5 V, 100 % = 4,2 V), le chargeur démarre à 0,1 C puis passe à 2 C (le maximum de la fiche des cellules), ralentit pendant que les résistances d'équilibrage déchargent les CORE les plus hauts — elles s'allument —, puis tient 4,2 V. Le temps court jusqu'à ×10 000 ; le départ, le courant pendant l'équilibrage et la résistance se règlent sur la fenêtre. Ce qui décide est le nouveau bloc « Passive balancing » du logiciel ; les cellules sont typiques, et c'est dit.", where: "#/swsim", sel: "[data-sw-balance-open]", how: "Charger « BM 8s8p - 21700 », Logiciel › Essayer." },
  { id: "sw-balancing-block", v: "0.196.0", title: "Logiciel : le bloc « Passive balancing »", text: "Un bloc qui tourne, en C prouvé dos à dos : un CORE se décharge par sa résistance tant qu'il dépasse le plus bas de plus de 20 mV, au-dessus de 3,90 V, et seulement quand le pack ne se décharge pas ; il s'arrête sous 10 mV. Le profil de charge du BM part de 3,0 V et raconte l'équilibrage.", where: "#/sw", sel: "[data-kind='balancing']", how: "Logiciel › Les blocs, bibliothèque « Batterie · BMS / ESS »." },
  { id: "sw-bench-pins", v: "0.195.0", title: "Logiciel : les broches et la carte, sans faux problème", text: "Une valeur que le logiciel relit de la chaîne RS-485 (tensions et température des CORE) est tenue par le banc : son étiquette dit « Banc », rien à relier. Une broche que la carte ne peut pas porter n'est plus « à corriger » : le guide dit, en conseil, qu'un net est à ajouter au PCBA — la simulation tourne. En Novice, la fiche d'une broche à relier montre le net à choisir. Deux broches sur la même voie ADC ou le même GPIO sont une erreur ; une nouvelle broche prend la première voie libre.", where: "#/sw", sel: "[data-sw-fix-tour]", how: "Logiciel › Les blocs : « n à corriger »." },
  { id: "sw-tour", v: "0.194.0", title: "Logiciel : « n à corriger », le tour guidé", text: "En haut à gauche des blocs, « n à corriger » ouvre un tour guidé : chaque chose que le guide signale, une à la fois, en mots, avec « Aller au bloc » (le bloc choisi, sa fiche ouverte, le champ qui clignote), « Précédent » et « Suivant ». Une chose corrigée sort de la liste.", where: "#/sw", sel: "[data-sw-fix-tour]", how: "Logiciel › Les blocs, en haut à gauche." },
  { id: "sw-quiz", v: "0.194.0", title: "Logiciel : le questionnaire des valeurs, et le « ? » des blocs", text: "« n valeurs à approuver » ouvre un questionnaire qui passe chaque bloc dont des valeurs sont à confirmer : ses valeurs en V, A, °C, d'où elles viennent, « Approuver » en haut à droite (une étape annulable), « Plus tard » pour y revenir. Rouvert, il ne montre que ce qui reste. Un « ? » orange marque le coin de chaque bloc à approuver ; un clic l'ouvre sur ce bloc.", where: "#/sw", sel: "[data-sw-quiz]", how: "Logiciel › Les blocs, en haut à gauche, ou le « ? » d'un bloc." },
  { id: "sw-loose", v: "0.194.0", title: "Logiciel : des exigences sans bout libre", text: "Un bloc du fichier d'exigences peut nommer toutes ses entrées et sorties (« inputs », « outputs », « SWR-024.close ») ; une porte ou un verrou prend aussi les identifiants que sa phrase cite. L'aperçu de l'import dit chaque bout libre — signal lu par aucun bloc, sortie commandée par aucun, entrée reliée à rien, bloc encore à venir — et un fichier qui déclare ses signaux devient un logiciel neuf (au choix : compléter celui qui est là).", where: "#/swreq", sel: "[data-sw-req-import]", how: "Logiciel › Ce qu'il doit faire › Importer." },
  { id: "sw-monitor", v: "0.193.0", title: "Logiciel : « Monitoring du BM-SWAP »", text: "Dans Essayer, le bouton « Monitoring du BM-SWAP » ouvre un tableau de bord qui flotte au-dessus de la page (ou dans sa propre fenêtre, pour un deuxième écran) : l'état général en vert, jaune ou rouge, une DEL par condition à surveiller avec sa valeur en volts, degrés ou ampères et son seuil, puis le contacteur, le défaut, la chaîne des cartes, la pompe et le buzzer. Il se lit dans le logiciel : rien à déclarer.", where: "#/swsim", sel: "[data-sw-monitor-open]", how: "Charger « BM 8s8p - 21700 », Logiciel › Essayer." },
  { id: "sw-lamp", v: "0.193.0", title: "Logiciel : un témoin d'état vert · jaune · rouge", text: "Un nouveau bloc, « Status lamp » : l'état du module sur trois DEL — vert, tout va bien ; jaune, à surveiller (dératé) ; rouge, limite dépassée (urgence, arrêt). Le logiciel du BM le porte, avec un buzzer sur le rouge — il s'entend doucement dans le haut-parleur de l'ordinateur — et une pompe de refroidissement eau-glycol (WEG) qui démarre à 45 °C.", where: "#/sw", sel: "[data-kind='state_lamp']", how: "Logiciel › Les blocs, bibliothèque « Batterie · BMS / ESS »." },
  { id: "sw-next", v: "0.193.0", title: "Logiciel : « Suivant », un événement à la fois", text: "« Suivant » joue un seul événement du profil, laisse le logiciel répondre, puis arrête tout : on lit l'état, les valeurs et les sorties avant de passer au suivant. Le récit est maintenant une bande sous la ligne du temps : il ne cache plus les pièces.", where: "#/swsim", sel: "[data-sw-story-next]", how: "Logiciel › Essayer, à côté de « Jouer le profil »." },
  { id: "sw-profiles", v: "0.193.0", title: "Logiciel : profils de charge et de décharge, banque de profils", text: "Un produit avec un ESS a deux profils de mission, Charge et Décharge, chacun avec ses événements critiques — la communication, la tension, le courant, la température — : on passe de l'un à l'autre d'un clic. « Banque » en ajoute d'autres : un .txt que l'on écrit, ou qu'une IA écrit d'après le prompt qui nomme les variables du banc ; chaque ligne fautive est dite avant d'ajouter.", where: "#/swsim", sel: "[data-sw-profile-bank]", how: "Logiciel › Essayer, au bout de la ligne du temps." },
  { id: "sw-story", v: "0.192.0", title: "Logiciel : le profil d'utilisation, raconté", text: "Sous les pièces de l'étape Essayer, une ligne du temps : « Jouer le profil d'utilisation » fait arriver les événements types un à un — mise sous tension, une température qui monte, un courant trop fort, la chaîne des cartes qui se tait — par les instruments du banc, comme le produit le vivrait. Une bulle raconte chaque événement puis ce que le logiciel et le produit répondent, et quand (« Contactor : ouvert, 1,49 s après ») ; le chronogramme reste dessous. Un clic sur un numéro rejoue jusqu'à cet événement.", where: "#/swsim", sel: "[data-sw-story-play]", how: "Logiciel › Essayer, sous les pièces." },
  { id: "sw-puzzle", v: "0.191.0", title: "Logiciel : la vue casse-tête, un seul lien par paire", text: "Le logiciel se lit en pièces de casse-tête, en trois bandes : Capter, Décider, Agir. Un capteur et le bloc qui le lit sont une seule pièce, une commande et sa broche aussi ; un seul lien joint deux pièces, combien de fils qu'il remplace (le nombre est écrit dessus). Pour relier : un clic sur le tenon d'une pièce, puis sur celle qu'elle nourrit — l'outil branche les bonnes interfaces en arrière-plan. « Blocs détaillés » montre les clés et chaque fil ; c'est la vue de l'Expert.", where: "#/sw/objects", sel: "[data-sw-view]", how: "Logiciel › Les blocs, en haut du centre." },
  { id: "sw-levels", v: "0.190.0", title: "Logiciel : trois niveaux — Novice, Intermédiaire, Expert", text: "En haut de chaque écran du Logiciel, choisissez votre niveau. Novice : 3 étapes (ce qu'il doit faire, les blocs, essayer), une phrase par étape, des blocs nus, et l'outil fait les choix. Intermédiaire : 5 étapes, la carte et les valeurs sur les blocs. Expert : le cycle en V complet. Le niveau est gardé par votre navigateur.", where: "#/sw/objects", sel: "[data-sw-level]", how: "Logiciel, en haut à droite." },
  { id: "sw-autoplace", v: "0.190.0", title: "Logiciel : en Novice, les blocs s'emboîtent tout seuls", text: "Un clic sur une brique la pose déjà emboîtée sur la dernière sortie libre de la même clé, à l'unité de ce qui la nourrit (un seuil posé après une CTN parle en °C, avec une valeur de référence de température). Un capteur arrive emboîté à son bloc de mesure, au milieu de sa plage.", where: "#/sw/objects", sel: "[data-device]", how: "Logiciel › Les blocs, niveau Novice." },
  { id: "sw-units", v: "0.190.0", title: "Logiciel : tout en unités de la physique", text: "Les afficheurs des blocs, les valeurs, les instruments du banc et l'écran d'analyseur parlent en V, A, °C, %, Wh — plus de millivolts ni de dixièmes de degré à l'écran. Ce que l'on tape est converti dans les entiers du logiciel, en arrière-plan.", where: "#/swsim", sel: ".swlab-lcd", how: "Logiciel › Essayer." },
  { id: "sw-ai-req", v: "0.190.0", title: "Logiciel : le bouton « IA » et les exigences de DynamiteAgile", text: "Le bouton « IA » des écrans du Logiciel donne le prompt du format standard, avec vos exigences, la carte et ses nets ; la réponse se colle, ou directement l'export .csv des exigences de DynamiteAgile (Goldmine). Une exigence déjà là n'est pas doublée : elle reçoit son bloc.", where: "#/swreq", sel: "[data-sw-req-import]", how: "Logiciel › Ce qu'il doit faire : « IA » en tête du volet, ou « Importer »." },
  { id: "sw-hil", v: "0.190.0", title: "Logiciel : essayer sur la vraie carte, pas à pas", text: "« Essayer sur la vraie carte » ouvre le même écran que la Manipulation en labo, sur la carte de l'Électronique : la sonde de programmation, l'alimentation réglée sortie coupée, le court-circuit cherché, la mise sous tension, le programme chargé, puis chaque entrée réglée par une source et chaque sortie relevée au multimètre — ce que le modèle attend, en volts.", where: "#/swsim", sel: "[data-sw-hil-open]", how: "Logiciel › Essayer, en tête du volet de gauche." },
  { id: "sw-blocks", v: "0.189.0", title: "Logiciel : des blocs à clés, de gauche à droite", text: "Les tuiles deviennent des blocs : chaque port a une clé selon ce qu'il porte (0 / 1 carré, grandeur ronde, comptes en queue d'aronde, commande en flèche, état en pointe), une sortie est une languette, une entrée une encoche de même forme, et le fil prend la couleur de son type. Les entrées de la carte à gauche, ses sorties à droite ; « Ranger de gauche à droite » range les blocs dans le sens du signal ; « Lire un bloc » donne la légende.", where: "#/sw/objects", sel: "[data-sw-arrange]", how: "Logiciel › 3. Conception, en haut à gauche des blocs." },
  { id: "sw-snap", v: "0.189.0", title: "Logiciel : les blocs s'emboîtent", text: "Approchez un bloc d'un autre : quand une languette arrive en face d'une encoche de la même clé, le bloc s'aimante, s'emboîte et la liaison se fait sans fil. L'écarter le déboîte. Ctrl + Z revient.", where: "#/sw/objects", sel: ".swb-block", how: "Logiciel › 3. Conception : glisser un bloc par sa tête." },
  { id: "sw-library", v: "0.189.0", title: "Logiciel : la bibliothèque par domaine, capteurs et actionneurs", text: "Le commun de tout logiciel embarqué (anti-rebond, temporisation, porte logique, régulateur PI, rampe, en plus des blocs d'avant), puis les capteurs et actionneurs typiques (CTN, Pt100, pont diviseur, courant à effet Hall, shunt, pression, potentiomètre, bouton, fin de course ; bobine, témoin, avertisseur, vanne, chauffage, ventilateur), la batterie, le robot, la puissance et l'appareil autonome. Ce que l'outil ne sait pas encore faire tourner est montré en pointillé, « à venir ».", where: "#/sw/objects", sel: "[data-sw-pack]", how: "Logiciel › 3. Conception, volet de gauche." },
  { id: "sw-reqin", v: "0.189.0", title: "Logiciel : partir de ses exigences, au format standard", text: "« Copier le prompt (format standard) » donne à un assistant ce qu'il faut pour convertir votre document d'exigences ; « Importer des exigences… » montre ce qui serait posé, puis pose les blocs, leurs valeurs et leurs fils en une étape annulable. Une valeur donnée par une exigence est verte (en pointillé tant que l'exigence n'est pas confirmée), une valeur de référence de l'outil est ambre, une valeur confirmée est bleue.", where: "#/sw/objects", sel: "[data-sw-req-import]", how: "Logiciel › 3. Conception, « Partir des exigences »." },
  { id: "sw-hwtag", v: "0.189.0", title: "Logiciel : chaque bloc dit sa carte", text: "Le logiciel est aligné sur la carte de commande du projet : chaque bloc porte son étiquette — la carte et le CPU, et pour une broche le net de la carte qu'elle lit ou commande (vert : relié ; ambre : à relier, choisi dans la fiche du bloc parmi les nets du microcontrôleur).", where: "#/sw/objects", sel: "[data-sw-tag]", how: "Logiciel › 3. Conception, sous la tête de chaque bloc." },
  { id: "sw-lab", v: "0.189.0", title: "Logiciel : la simulation devient un banc de labo", text: "Comme au Labo d'une carte : au-dessus des blocs, un instrument par entrée du logiciel, réglé sur sa face (afficheur dans l'unité du capteur, bouton, comptes à la broche), les interrupteurs et leur témoin, et les témoins de ce que le logiciel commande ; dessous, le chronogramme sur un écran d'analyseur. Les fils qui portent un 1 s'allument, ceux dont la grandeur bouge défilent.", where: "#/swsim", sel: "[data-sw-rack]", how: "Logiciel › 4. Simulation." },
  { id: "name-dynamiteorbit", v: "0.188.0", title: "Le nom officiel : DynamiteOrbit.ai", text: "« DesignOrbit » était une erreur : la barre du haut, l'accueil, le logo, la marque de chaque document, le film et ses sous-titres portent maintenant DynamiteOrbit.ai. La fusée du compas reste ; les fichiers .dwiz et les projets gardés s'ouvrent comme avant.", where: "#/home", sel: ".brand-name", how: "En haut à gauche de chaque écran." },
  { id: "launch-tower", v: "0.187.0", title: "La tour de lancement : où cet écran se tient", text: "Le bouton « Tour », à côté du projet sous le titre du volet de gauche, ouvre une tour lue du pied vers le haut : le projet, les assemblages qui tiennent l'artéfact, l'artéfact, puis l'écran où vous êtes, la fusée allumée. Chaque étage se clique et dit ce que le guide y trouve.", where: "#/shop", sel: ".where-flap", how: "Volet de gauche de tout écran d'un projet : « Tour »." },
  { id: "where-line", v: "0.186.0", title: "Où suis-je : le projet et l'artéfact sous le titre", text: "Sous la tête du volet de gauche de chaque écran : le projet, puis la pièce, l'assemblage, la carte, la feuille ou le logiciel que l'écran montre. Un clic sur le projet ouvre l'Atelier.", where: "#/shop", sel: ".where-line", how: "Volet de gauche de tout écran, sous son titre et ses boutons." },
  { id: "nav-calc", v: "0.186.0", title: "Physique et Simulation : une seule tuile", text: "Dans le menu Mécanique, « Physique · Simulation » remplace les tuiles 5 et 6 ; les deux écrans se passent la main par leurs onglets, comme avant.", sel: ".nav-group", how: "Barre du haut › Mécanique › 5 Physique · Simulation." },
  { id: "seen-gone", v: "0.185.0", title: "Une nouveauté cochée « vu » quitte l'écran", text: "La marque verte « Vu » ne reste plus sur l'élément : la coche reste dans la liste, datée, pour la trace ; décocher fait revenir la marque.", where: "#/home", sel: "#news-btn", how: "Bouton à l'étoile de la barre du haut." },
  { id: "icon-scale", v: "0.184.0", title: "Icônes du haut plus grandes, au choix", text: "Les icônes de la barre du haut, du fil d'Ariane, des onglets de travail et de la tête des volets de gauche et de droite grandissent : × 1,25 d'office, de × 1 à × 1,75 au choix ; le texte garde sa taille.", where: "#/account", sel: ".account-icon-scale", how: "Menu du compte (le bonhomme, en haut à droite) › « Taille des icônes du haut », ou la page Compte." },
  { id: "bm-c4", v: "0.183.0", title: "BM concept 4 : faces planes à lamelles, rien ne dépasse", text: "Une quatrième branche du projet BM, partie du concept 3 : plus de lame ni de pince ; sur la face − de chaque CORE, deux bandes à lamelles dans des rainures, au ras d'un cadre isolant ; la face + est plate. Le boîtier retrouve la largeur du concept 1 et garde 32,9 mm de moins en longueur.", where: "#/home", sel: "[data-example=\"bm\"]", how: "Accueil : la carte « BM 8s8p - 21700 » s'ouvre sur la branche « concept 4 - flat louvred faces » ; Produit › Historique pour comparer aux concepts 1 à 3." },
  { id: "bm-c3-bottom", v: "0.182.0", title: "BM concept 3 : le bout bas raccourci de 20,75 mm", text: "Plus d'entretoises au couvercle du fond : le boîtier s'arrête 1 mm derrière la plaque d'appui de la borne −, l'anneau y appuie par ses pattes, et le couvercle du fond, son connecteur, son contacteur et ses barres remontent d'autant. Le boîtier a maintenant 33,65 mm de moins qu'au concept 1.", where: "#/home", sel: "[data-example=\"bm\"]", how: "Accueil : la carte « BM 8s8p - 21700 », puis le sous-assemblage « Couvercle du fond » ; Produit › Historique pour comparer P6 et P7." },
  { id: "bm-c3-fixed", v: "0.181.0", title: "BM concept 3 : le retour fixe, sans pont", text: "La borne + et le busbar de retour sont reliés pour de bon par un shunt souple ; le pont du couvercle et ses deux pinces sont partis ; le couvercle ne fait plus que tenir la pile. Le boîtier perd encore 8,15 mm — 12,9 mm de moins qu'au concept 1 ; ce qui fixe la longueur est maintenant la pince de la borne +.", where: "#/home", sel: "[data-example=\"bm\"]", how: "Accueil : la carte « BM 8s8p - 21700 » ; Produit › Historique pour comparer P5 et P6." },
  { id: "bm-c3-short", v: "0.180.0", title: "BM concept 3 : le bout haut raccourci de 4,75 mm", text: "La plaque de pression appuie directement sur la borne + ; la languette du busbar de retour passe juste derrière, dans une fenêtre de la plaque ; la pince B, le pont, le couvercle et le boîtier suivent : le module perd 4,75 mm. Un troisième point sur la branche du concept 3.", where: "#/home", sel: "[data-example=\"bm\"]", how: "Accueil : la carte « BM 8s8p - 21700 » ; Produit › Historique pour comparer les points du concept 3." },
  { id: "bm-c3-lid", v: "0.179.0", title: "BM concept 3 : le couvercle du haut en lame et pince", text: "La borne + et la languette du busbar de retour portent chacune une pince en creux ; le couvercle porte un pont de cuivre rigide à deux lames qui s'y branchent quand on le ferme. Couvercle retiré, le cuivre du module reste en retrait ; le shunt souple et les ressorts des plots sont partis, les rondelles ressorts tiennent seules la pile. Un second point sur la branche du concept 3.", where: "#/home", sel: "[data-example=\"bm\"]", how: "Accueil : la carte « BM 8s8p - 21700 », puis le sous-assemblage « Couvercle du haut, verrouillé » ; Produit › Historique pour comparer les deux points du concept 3." },
  { id: "rocket-icons", noMark: true, v: "0.178.0", title: "Icônes et logo du monde des fusées", text: "Le chapeau de sorcier devient une tour de lancement et sa fusée, sur tous les boutons qui confient une tâche à l'assistant ; toutes les icônes suivent une même ligne, aux coins arrondis comme des panneaux (Le.Carnet garde son crayonné) ; le logo devient une fusée qui quitte le compas sur sa trajectoire, sur l'écran comme sur chaque document.", where: "#/home", sel: ".topbar .wand" },
  { id: "orbit-mark", noMark: true, v: "0.177.0", title: "Le symbole de DynamiteOrbit (remplacé en v0.178.0)", text: "L'éclair mis en orbite remplace le compas : le carré jaune et l'éclair de la famille DynamiteAgile, une orbite bleue, une étincelle orange. « Dynamite » s'écrit en orange en haut à gauche ; les PDF, les documents Word, les étiquettes et l'onglet du navigateur portent le nouveau symbole.", where: "#/home", sel: ".brand-name", how: "En haut à gauche de chaque écran, et dans l'onglet du navigateur." },
  { id: "bm-c3-fork", v: "0.176.0", title: "BM concept 3 : la pince détaillée", text: "Chaque mâchoire a le logement de sa bande à lamelles (1,2 mm) et laisse 0,5 mm d'air contre la lame, qui est guidée ; la lame a un nez chanfreiné et un talon brasé sous le bout de l'oreille ; les mâchoires ont une bouche chanfreinée. L'effort des lamelles est celui de la fiche de la bande, lue (5 à 30 N par pont) ; la mâchoire est vérifiée au plus fort : 0,046 mm de flèche.", where: "#/home", sel: "[data-example=\"bm\"]", how: "Accueil : la carte « BM 8s8p - 21700 » (branche « concept 3 - blade and fork »), puis le sous-assemblage « CORE 1S8P », bout +X." },
  { id: "bm-c3", v: "0.175.0", title: "BM concept 3 : la lame dans la pince", text: "Une troisième branche du projet BM, partie du concept 1 : chaque joint entre deux CORE est une lame de cuivre de 2,5 mm qui entre dans une pince du CORE suivant, entre deux bandes à lamelles (32 lamelles, 1 280 A assignés pour 360 A, 3,4 mV) — l'effort de contact reste dans la pince ; les bornes du module de même ; des rondelles ressorts au couvercle du haut ; le boîtier 10 mm plus large au bout +X, sans un millimètre de longueur.", where: "#/home", sel: "[data-example=\"bm\"]", how: "Accueil : la carte « BM 8s8p - 21700 » s'ouvre sur la branche « concept 3 - blade and fork » ; Produit › Historique pour revenir au concept 1 ou 2." },
  { id: "rename-orbit", noMark: true, v: "0.174.0", title: "Le nouveau nom : DynamiteOrbit.ai", text: "DesignWizard.ai devient DynamiteOrbit.ai, de la famille DynamiteAgile : la barre du haut, l'accueil et la marque de chaque document portent le nouveau nom. Les fichiers .dwiz et les projets déjà gardés s'ouvrent comme avant.", where: "#/home", sel: ".brand-name", how: "En haut à gauche de chaque écran ; et sur tout document produit (PDF, Word, dessins)." },
  { id: "face-cam", v: "0.173.0", title: "Calculs : une came de face tournée par une poignée", text: "Un nouveau modèle analytique : la course, l'effort sur ce que la came presse, le couple et l'effort à la main pour fermer et pour ouvrir, et si la rampe tient seule — la mécanique d'une vis à filet carré (page Wikipédia « Leadscrew », lue), avec le frottement de la butée. Rejoué contre un rendement publié (35 % à λ = 10°, μ = 0,30) ; ce que ce cas ne couvre pas est dit.", where: "#/physics", sel: "[data-model='face_cam']", how: "Calculs › Modèles analytiques, groupe « Assemblages », tuile « Face cam · handle »." },
  { id: "bm-c2-cam", v: "0.173.0", title: "BM concept 2 : la came détaillée", text: "La came du couvercle du haut est dessinée : deux rampes de 5,5° sous deux goupilles d'appui du couvercle, un plateau de fin de course, un ergot entre deux goupilles de butée, une butée à aiguilles ; elle flotte sur sa clavette, l'arbre à collet ne porte que le couple, un circlip le tient. Son calcul est gardé sur la branche : 378 N sur la pile, 33 N à la main, la rampe tient seule.", where: "#/home", sel: "[data-example=\"bm\"]", how: "Accueil : la carte « BM 8s8p - 21700 », puis le sous-assemblage « Couvercle du haut à poignée »." },
  { id: "bm-c2-sense", v: "0.172.0", title: "BM concept 2 : capteurs et tension", text: "Le CORE 2.0 mesure de nouveau : un flex glissé entre ses deux rangées de cellules porte 8 thermistances, chacune sur sa pastille contre le flanc de sa cellule, sa queue sous le bord de la carte ; deux prises de tension montent des plaques + et − à la carte.", where: "#/home", sel: "[data-example=\"bm\"]", how: "Accueil : la carte « BM 8s8p - 21700 », puis le sous-assemblage « CORE 2.0 »." },
  { id: "bm-concept-2", v: "0.171.0", title: "BM : le concept 2, sur sa branche", text: "Le projet BM s'ouvre sur la branche « concept 2 - consumer product interface » : les CORE couchés en ligne et pressés comme des piles, des bandes à lamelles sur la face −, la plaque + rigide à bossages, une poignée quart de tour à came double lobe, le couvercle du fond actif avec la carte du BMS. Le concept 1 est gardé sur MAIN (Produit › Historique).", where: "#/home", sel: "[data-example=\"bm\"]", how: "Accueil : la carte « BM 8s8p - 21700 », puis Produit › Historique pour voir les deux concepts." },
  { id: "history-erase", v: "0.170.0", title: "Historique : effacer un point", text: "« Effacer ce point », dans la marge de droite de tout point : les points d'après se rattachent au point d'avant, chaque branche garde son nom ; une branche qui n'avait que ce point disparaît, et si vous y étiez, le produit revient au dernier point de MAIN. Ce que cela fait est dit avant ; un point effacé ne revient pas.", where: "#/history", sel: "[data-history-erase]", how: "Produit › Historique : choisir un point, « Effacer ce point »." },
  { id: "lab-move-lead", v: "0.169.0", title: "Labo : déplacer un cordon à la souris", text: "« Montage verrouillé » d'office. Déverrouillé, un cordon d'appareil se prend par sa pastille et se pose sur une pastille de la carte : l'outil refuse ce qui abîmerait la carte ou ne voudrait rien dire (court-circuit, pince de masse sur un point vivant, pastille hors du bloc), et dit pourquoi ; sinon l'essai est simulé de nouveau avec ce montage, en une étape annulable.", where: "#/elab", sel: ".lab-lock", how: "Labo : « Montage verrouillé », en haut à gauche de la vue, puis glisser une pastille de cordon." },
  { id: "lab-breadboard", v: "0.168.0", title: "Labo : la plaque d'essai", text: "À côté de la carte, une plaque d'essai : chaque point que touche un appareil sort par son fil vers sa rangée, étiquetée de la référence, de la broche et du signal (« C3.1 · VIN ») ; les cordons des appareils arrivent dans les trous de la rangée, chacun étiqueté (« Alim. + », « Osc. S2 »). Les fils ne se croisent jamais. « Carte » revient à la vue d'avant.", where: "#/elab", sel: ".lab-viewmode", how: "Labo : « Plaque d'essai · Carte », en haut à gauche de la vue." },
  { id: "draw-detail-radius", v: "0.167.0", title: "Dessins : un rayon se donne aussi sur la vue de détail", text: "Une cote par repère — un rayon de coin — dont le point tombe dans le cercle d'une vue de détail passe sur le détail : la flèche part du coin agrandi, la note et sa bulle à droite du détail. Une cote se donne une fois, là où elle se lit le mieux.", where: "#/drawings", sel: ".detail-row", how: "Dessins : tracer un détail sur un coin arrondi (« Choisir une zone »)." },
  { id: "lab-gen-face", v: "0.166.0", title: "Labo : le générateur se règle sur sa face", text: "Le générateur de fonctions se règle comme l'alimentation : niveau haut, niveau bas et fréquence se tapent sur l'appareil dessiné, et l'essai est simulé de nouveau — la fiche, la manipulation et le plan suivent. Un signal écrit point par point, ou une réponse en fréquence, le dit et ne se règle pas.", where: "#/elab", sel: ".gear-card", how: "Labo : un essai qui pose un générateur (un amplificateur, un comparateur…) — les champs sont sur l'écran du générateur." },
  { id: "bm-state", v: "0.165.0", title: "Logiciel : la machine à états d'un module", text: "Un nouvel objet à poser dans le Logiciel : normal, dératé, urgence, arrêt (contacteur ouvert). Le projet BM 8s8p a désormais son logiciel : sur son banc, le module se dérate au-dessus de 95 A, passe en urgence quand la chaîne des cartes se tait, puis s'arrête — et le C que l'outil en écrit imprime les mêmes pas.", where: "#/sw", sel: "[data-kind='module_state']", how: "Charger « BM 8s8p - 21700 », puis Logiciel › 3 Conception : la tuile « Module state »." },
  { id: "bm-bms", v: "0.164.0", title: "BM : la carte du BMS central, de ses fonctions à son cuivre", text: "Dans le projet BM 8s8p, une deuxième carte : le BMS central — 12 V du véhicule, chaîne RS-485 isolée vers les 8 CORE (il en alimente le côté bus), courant du module lu sur un capteur de la barre de retour, contacteur commandé et relu, CAN vers le véhicule. Tout routé, sans erreur ; sur la table du labo avec une carte de CORE, les quatre fils de la chaîne reliés d'office.", where: "#/elab/table", sel: ".lab-table-host", how: "Charger « BM 8s8p - 21700 », puis Électronique › PCBA (carte BMS-CENTRAL-PCBA) ou Labo › La table." },
  { id: "plastic-screw", v: "0.163.0", title: "Calculs : une vis autotaraudeuse dans un bossage plastique", text: "Un nouveau modèle analytique : l'effort qui arrache le filet qu'une vis a formé dans un plastique, F = Ss π Dp L avec Ss = St / √3, tel que l'imprime une page publique lue ; le plastique vient de la base des médias ; une prise courte et un bossage mince sont dits. Aucun exemple publié ne l'a validé, et l'écran le dit.", where: "#/physics", sel: "[data-model='plastic_screw']", how: "Calculs › Modèles analytiques, groupe « Assemblages », tuile « Screw in plastic · pull-out »." },
  { id: "bm-heat", v: "0.163.0", title: "BM : la tenue des vis et l'échauffement du module fermé", text: "Trois calculs gardés dans le projet BM 8s8p : les vis des couvercles dans le boîtier (marge de 8,7, et un lobe plus mince que la règle) ; le module fermé à 360 A, qui atteint la limite de ses cellules en 3 min ; le courant qu'il tient pour toujours, 95 A.", where: "#/physics", sel: "[data-model='lumped_mass']", how: "Charger « BM 8s8p - 21700 », puis Calculs › Modèles analytiques : les calculs gardés sous BM-CASING." },
  { id: "edu-molded", v: "0.162.0", title: "Deux pièces moulées, pour apprendre", text: "Un nouvel exemple à l'accueil : une coque injectée en plastique (paroi unique, dépouilles, nervures, bossages, point d'injection en bord) et une équerre en aluminium injecté sous pression, reprise en usinage — de la conception au moule, à la gamme jouée, au dessin et à ce qui part au fournisseur. Les règles viennent du registre des sources, avec un guide public lu.", where: "#/home", sel: "[data-example]", how: "Accueil : la carte « Deux pièces moulées »." },
  { id: "fab-mould-plan", v: "0.162.0", title: "Atelier de fab : le moule de la pièce, et ses reprises", text: "Le moule dessiné est celui de la pièce : les demi-moules se séparent à son plan de joint, la carotte et le canal mènent à son point d'injection, les overflows sont en face de l'ingate. Une pièce coulée reste brute de fonderie jusqu'à ses reprises, faites en posages d'usinage — la face surfacée d'abord.", where: "#/fab", sel: "[data-step]", how: "Atelier de fab : l'étape 10 d'une pièce moulée ou coulée." },
  { id: "demo-inverter", v: "0.161.0", title: "Démonstration : un onduleur de traction sur son moteur", text: "Un nouvel exemple à l'accueil : le boîtier moulé d'un onduleur triphasé posé sur son moteur — côté courbe, pans coupés, trois cavités de hauteurs différentes, couvercle embouti et joint collé, étage de puissance potté, busbar laminé. Aucune marque, aucun dessin copié.", where: "#/home", sel: "[data-example]", how: "Accueil : la carte « Onduleur de traction »." },
  { id: "lab-table", v: "0.160.0", title: "La table du labo : plusieurs cartes", text: "Les cartes posées sur la même table, leurs câbles reliés d'office quand leurs connecteurs portent les mêmes nets ; deux vues, « Table » et « Schéma des liaisons » ; l'alimentation du banc cordée à la carte que rien ne nourrit.", where: "#/elab/table", sel: ".lab-table-host", how: "Électronique › Labo : « La table », puis « Exemple : trois cartes »." },
  { id: "lab-lock", v: "0.160.0", title: "Montage verrouillé, ou déverrouillé pour câbler à la souris", text: "Le montage de la table est verrouillé d'office ; déverrouillé, un câble se pose d'un clic à l'autre ou d'un glisser, vérifié — l'outil refuse une masse sur une alimentation, deux tensions différentes, une paire croisée, et dit pourquoi.", where: "#/elab/table", sel: ".lab-lock", how: "La table du labo : « Montage verrouillé » en tête du centre." },
  { id: "board-role", v: "0.159.0", title: "Le rôle d'une carte : Produit ou Banc d'essai", text: "En tête du PCBA, chaque carte dit si elle est du produit ou un outil du banc d'essai. Une carte de banc se conçoit et s'essaie comme les autres, mais n'a pas de jumeau mécanique, n'entre pas dans l'isolation du produit et le rapport la range à part.", where: "#/pcba", sel: ".role-switch", how: "Électronique › PCBA : « Produit · Banc d'essai », à côté de la révision." },
  { id: "detail-asm", v: "0.158.0", title: "Une vue de détail sur un dessin d'assemblage", text: "« Choisir une zone » marche aussi sur le dessin d'un assemblage : un cercle tracé sur une vue devient DETAIL D, posé dans le blanc de la feuille, hors des vues, de la nomenclature et du cartouche.", where: "#/drawings", sel: ".detail-pick", how: "Mécanique › Dessins, un assemblage : marge de droite, « Choisir une zone », puis un cercle sur une vue." },
  { id: "detail-dims", v: "0.158.0", title: "Les cotes d'une zone, sur son détail", text: "Une cote dont les deux points tombent dans le cercle d'un détail se donne sur le détail — une fois, comme le veut l'ASME Y14.5 ; la ligne du détail dit combien il en porte.", where: "#/drawings", sel: ".detail-row", how: "Mécanique › Dessins, une pièce : tracez une zone autour d'un trou coté ; sa cote passe sur DETAIL D." },
  { id: "detail-move", v: "0.158.0", title: "Un détail se déplace à la main", text: "Sur la feuille, un détail se glisse où l'on veut et y reste ; « ↻ » sur sa ligne le remet dans le blanc. Les vues de face, de dessus et de droite restent alignées.", where: "#/drawings", sel: ".detail-row", how: "Mécanique › Dessins : appuyez sur un détail de la feuille, glissez, relâchez." },
  { id: "ai-disturb", v: "0.157.0", title: "Ce que cela dérange, à l'import d'une réponse d'IA", text: "Sous chaque artéfact qu'une réponse modifie : ce que le changement fait ailleurs dans le produit — rompu (interface, accouplement), à refaire (calcul, simulation, vues de détail, isolation), à regarder (assemblage, révision gelée).", where: "#/shop/ai", sel: ".ai-disturb", how: "Atelier › Avec l'IA : rapportez une réponse qui modifie une pièce ; la boîte apparaît sous sa ligne. Aussi dans le bouton « IA » de chaque écran." },
  { id: "ai-accept", v: "0.157.0", title: "Une réponse d'IA acceptée artéfact par artéfact", text: "Dans l'aperçu de la porte « Avec l'IA », chaque artéfact créé ou modifié a son interrupteur On / Off : seul ce qui est accepté est appliqué ; refuser une pièce nouvelle refuse aussi l'assemblage qui la monte.", where: "#/shop/ai", sel: ".ai-art .switch", how: "Atelier › Avec l'IA, après « Lire » : l'interrupteur au début de chaque ligne." },
  { id: "lab-gear", v: "0.156.0", title: "Le banc réglé sur l'appareil", text: "Au-dessus de la carte du Labo, les appareils de l'essai sont dessinés, leurs cordons tirés jusqu'aux points de la carte ; la tension et la limite de l'alimentation, la résistance de la charge se tapent sur l'écran de l'appareil — l'essai, la fiche et le plan suivent, Ctrl + Z revient en arrière. Ce qui ne se règle pas le dit.", where: "#/elab", sel: ".gear-card", how: "Électronique › Labo : choisissez un bloc ; tapez une tension sur l'écran de l'alimentation, puis Entrée." },
  { id: "lab-press", v: "0.156.0", title: "Un bouton de la carte s'appuie dans la vue", text: "Dans le Labo, un essai qui demande d'appuyer sur un bouton : tenez le clic sur le bouton dans la vue de la carte — la DEL s'allume, le doigt dessiné appuie ; relâchez, elle s'éteint.", where: "#/elab", sel: ".lab-part.pressable", how: "Labo de la première carte, bloc « Bouton et témoin » : clic tenu sur SW1." },
  { id: "share", v: "0.155.0", title: "Partager, sur chaque studio", text: "En tête du volet de gauche, à côté de « IA » : « Partager » copie le lien de l'élément et rassemble les fichiers que l'écran sait faire — STEP, PDF, Word, Excel, Gerber, dossiers — groupés par nature ; sur une vue 3D, une animation d'un tour s'enregistre en vidéo.", where: "#/assembly", sel: ".head-share", how: "Mécanique › Assemblage : le bouton « Partager » en tête du volet de gauche." },
  { id: "auto-dock", v: "0.155.0", title: "La rotation automatique se déplace ou se range", text: "Le panneau de la rotation automatique se déplace par sa poignée, ou se range dans la marge de droite (⇥) ; sa place est gardée pour la fois suivante.", where: "#/assembly", sel: ".dw-auto-dock", how: "Maintenez le clic 2 secondes sur la pièce : le panneau s'ouvre ; glissez son titre, ou cliquez ⇥." },
  { id: "auto-record", v: "0.155.0", title: "Une animation de la vue, enregistrée", text: "Dans le panneau de la rotation automatique : « Enregistrer » filme la vue jusqu'au clic suivant, « Un tour enregistré » fait un tour complet et le télécharge en vidéo WebM, avec la marque — pour une revue de conception.", where: "#/assembly", sel: ".dw-auto-record", how: "Ouvrez la rotation automatique (clic maintenu 2 s), puis « ● Enregistrer » ou « ↻ Un tour enregistré »." },
  { id: "bm-core-12", v: "0.154.0", title: "BM 8s8p : le CORE refait", text: "Itération 12 : le busbar laminé du CORE a ses deux couches empilées sur le dessus, comme un busbar laminé industriel, avec des languettes minces soudées au laser sur chaque calotte et chaque épaule — les cordons sont dessinés. Les CORE se touchent face contre face, pressés par les ressorts du couvercle (borne de Holm gardée) ; les contacts LV affleurent ; les capteurs sont des cônes du flex, glissé dans le support du bas.", where: "#/assembly/BM-CORE-ASM", sel: ".viewport", how: "Accueil › BM 8s8p - 21700, puis le CORE 1S8P dans le menu de l'Assemblage ; une coupe montre les couches du busbar et les cônes sous les cellules." },
  { id: "stairs-asm-part", v: "0.153.0", title: "De l'assemblage à la pièce, d'un clic", text: "En tête du volet de l'Assemblage, une marche vers le haut ramène à la pièce d'où l'on vient (ou, sinon, à la première pièce de l'assemblage) : plus besoin de passer par le menu Mécanique pour retourner aux Pièces. Alt + ↑ aussi.", where: "#/assembly", sel: ".stair-btn", how: "Mécanique › Pièces, une pièce ; descendre à son assemblage, puis la flèche vers le haut à côté du titre « Assemblages »." },
  { id: "look-opaque", v: "0.153.0", title: "« Opaque » tient, même sur une matière transparente", text: "Une pièce en polycarbonate (le boîtier du module BM) ou une occurrence d'une pièce transparente devient vraiment opaque quand on choisit « Opaque » ; la palette allume le réglage que l'on voit, pas « Opaque » par défaut. « Satiné » tient de la même façon.", where: "#/assembly", sel: "[data-opacity]", how: "Assemblage du module BM, clic droit sur le boîtier › Apparence : une couleur, puis « Opaque »." },
  { id: "stairs-one-sub", v: "0.153.0", title: "Un seul bouton pour les sous-assemblages", text: "Dans un assemblage qui en contient plusieurs, les marches vers le bas ne montrent plus un bouton par sous-assemblage : un seul, vers celui qui revient le plus souvent (le CORE d'un module) ; les autres sont dans le menu du fil d'Ariane, et l'Isolation et le Dessin d'ensemble restent dans la rangée.", where: "#/assembly", sel: ".stair-downs", how: "Mécanique › Assemblage, un assemblage qui contient des sous-assemblages : les pictogrammes à flèche vers le bas, en tête du volet de gauche." },
  { id: "stairs-part-asm", v: "0.152.0", title: "D'une pièce à son assemblage, d'un clic", text: "Dans Pièces, à côté du Dessin, une marche vers le bas mène maintenant à l'assemblage où la pièce est montée : plus besoin de passer par le menu Mécanique.", where: "#/parts", sel: ".stair-downs", how: "Mécanique › Pièces, une pièce qui entre dans un assemblage : les pictogrammes à flèche vers le bas, en tête du volet de gauche." },
  { id: "bm-bottom-lid", v: "0.152.0", title: "BM 8s8p : le couvercle du fond", text: "Le couvercle du fond : un anneau d'aluminium et quatre entretoises qui portent la poussée de la pile, un logement moulé, le connecteur d'échange (enveloppe générique), le contacteur sur le pôle +, le volume de la carte BMS centrale. Les barres de puissance sont passées à 40 × 4 mm, ce que le calcul demande pour 360 A — le shunt du couvercle du haut aussi.", where: "#/home", sel: "[data-example='bm']", how: "Accueil, « Exemples », carte « BM 8s8p - 21700 » (un nouveau projet), puis l'assemblage « Couvercle du fond » ou le module." },
  { id: "bm-top-lid", v: "0.151.0", title: "BM 8s8p : le couvercle du haut et le busbar de retour", text: "Le busbar de retour court dans le canal du boîtier et se relève au bout haut. Le couvercle du haut se visse par un anneau d'aluminium et se verrouille d'un quart de tour : ses ressorts pressent la pile des 8 CORE, et son pont de contact — un plot sur la borne +, un sur le busbar de retour, chacun sur sa bande à lamelles — ferme la boucle par pression ; le couvercle retiré, le module est ouvert. Les efforts sont tenus en un seul endroit (780 N, 195 N par vis).", where: "#/home", sel: "[data-example='bm']", how: "Accueil, « Exemples », carte « BM 8s8p - 21700 » (un nouveau projet), puis l'assemblage « Couvercle du haut, verrouillé » ou le module." },
  { id: "history-merge-point", v: "0.150.0", title: "Historique : fusionner dans MAIN depuis un point de branche", text: "Sur tout point d'une branche, la marge de droite porte « Fusionner dans MAIN » : en bleu quand la branche apporte quelque chose, sinon il dit pourquoi il n'y a rien à fusionner. Il fusionne jusqu'à ce point — ce qui est venu après reste dans la branche — avec l'aperçu d'abord, en une étape annulable, et vous ramène sur MAIN.", where: "#/history", sel: "[data-history-merge-point]", how: "Produit › Historique : choisissez un point d'une branche dans l'arbre, puis « Fusionner dans MAIN » dans la marge de droite." },
  { id: "history-fork", v: "0.149.0", title: "Historique : « Nouvelle branche ici »", text: "Une branche parallèle s'ouvre maintenant d'un clic, sur n'importe quel point — le dernier de MAIN compris : on la nomme, son premier point « Départ de … » se pose tout de suite et la branche paraît dans l'arbre, à côté ; la branche d'où elle part ne bouge pas. « Revenir à MAIN » et « Travailler sur cette branche » passent de l'une à l'autre ; « Fusionner dans MAIN » ne paraît que lorsque la branche apporte quelque chose.", where: "#/history", sel: "[data-history-fork-here]", how: "Produit › Historique : « Nouvelle branche » dans la section « Les branches », ou « Nouvelle branche ici » dans la marge de droite d'un point choisi dans l'arbre." },
  { id: "bm-casing", v: "0.148.0", title: "BM 8s8p : le boîtier extrudé et les bornes du module", text: "Un boîtier de polycarbonate extrudé le long des 8 CORE : les CORE glissent sur deux rails du fond, tenus par quatre nervures de côté, 0,5 mm de jeu ; un lobe à chaque coin porte un trou fermé où une vis pour plastiques fera son filet au premier vissage — trou, profondeur et lamage d'après la recommandation publiée du fabricant de la vis ; sous le fond, le canal du busbar de retour (50 × 4 mm, calculé). Les deux bornes ferment la chaîne : la − porte les bandes, les butées et les contacts LV d'une jambe +, la + est plane comme une jambe − et reçoit la terminaison du bus RS-485. Dans l'atelier de fab, le boîtier se joue : extrudé, coupé, ses bouts percés, alésés et lamés le long d'un parcours écrit par une IA.", where: "#/home", sel: "[data-example='bm']", how: "Accueil, « Exemples », carte « BM 8s8p - 21700 » (un nouveau projet), puis l'assemblage du module ; ou la pièce « Boîtier extrudé du module » dans l'Atelier de fab." },
  { id: "louvre-strip", v: "0.147.0", title: "Calculs : une bande de contact à lamelles entre deux faces planes", text: "Un nouveau modèle analytique (Assemblages) qui ne fait que ce que les fabricants impriment : le nombre de lamelles (longueur / pas), le courant assigné du joint (n × celui d'une lamelle, déclassé par la matière d'en face), sa résistance (Rk / n), la chute de tension et sa classe, les pertes, l'effort pour fermer le joint, et la hauteur tenue par les butées contre la plage de travail de la bande — aussi dans le classeur Excel.", where: "#/physics", sel: "[data-model='louvre_strip']", how: "Calculs › Modèles analytiques, groupe « Assemblages », tuile « Louvre strip · flat joint »." },
  { id: "bm-louvres", v: "0.147.0", title: "BM 8s8p : bandes à lamelles et quatre contacts LV", text: "Entre deux CORE : deux bandes à lamelles de l'enveloppe d'une bande du commerce dans leur cadre, quatre butées qui tiennent l'écart de travail publié, quatre contacts LV (A, B, +5V_ISO, GND_ISO) sur des îlots, et les queues du flex qui montent à chaque îlot ; le joint le plus haut de la chaîne s'analyse dans l'écran Isolation (assemblage « Joint entre deux CORE »).", where: "#/home", sel: "[data-example='bm']", how: "Accueil, « Exemples », carte « BM 8s8p - 21700 » (un nouveau projet), puis l'assemblage « CORE 1S8P », ou l'Isolation sur « Joint entre deux CORE »." },
  { id: "fab-played", v: "0.146.0", title: "Atelier de fab : seulement ce qu'il sait montrer juste", text: "Les pièces usinées, moulées ou coulées, extrudées, embouties ou découpées au laser se jouent ; les cartes, les circuits flexibles, les pièces achetées ou laminées et l'impression 3D ne se jouent plus — la marge de gauche dit lesquelles et pourquoi, leur gamme écrite reste dans l'onglet « Gamme ». Au tour, la pièce est couchée dans l'axe du mandrin ; une pièce tout usinée part d'un brut supposé, dit comme tel.", where: "#/fab", sel: "[data-fab-off]", how: "Mécanique › Atelier de fab : la marge de gauche, « Ne se jouent pas ici »." },
  { id: "fab-path", v: "0.146.0", title: "Atelier de fab : l'outil usine le long d'un parcours écrit par une IA", text: "Dans une phase d'usinage, « Parcours d'outil » : l'outil ne l'écrit pas, Claude (ou l'IA de votre choix) l'écrit — la demande est prête, avec la phase, ses perçages, le repère et le format (G-code simple ou positions). L'écran le lit, le vérifie contre la pièce (l'étau, les rapides dans la matière) et l'anime : la pièce d'avant la phase, le foret, le taraud ou l'outil de tournage le long du parcours, puis la pièce d'après. Trois exemples écrits par une IA : le dissipateur du variateur, le disque et la jupe de tuyère de la fusée.", where: "#/fab", sel: "[data-fab-path]", how: "Mécanique › Atelier de fab › DRV-HEATSINK, phase 20 : « Usiner »." },
  { id: "fab-shop", v: "0.145.0", title: "Atelier de fab : la gamme d'une pièce, jouée étape par étape", text: "Le dernier écran du groupe Mécanique : la pièce telle qu'elle est après chaque phase, tournée vers l'outil et posée dans le montage de son poste — étau sous la broche, mandrin, presse plieuse, table laser, moule, plateau d'impression, établi, marbre, carton —, dessiné par l'outil (un montage de principe). « Jouer la gamme » enchaîne les étapes ; à droite, la prise de pièce, les opérations, ce que la pièce mesure, la note de l'atelier.", where: "#/fab", sel: ".fab-flow", how: "Mécanique › Atelier de fab (ou la marche vers le bas d'une pièce)." },
  { id: "fab-order", v: "0.145.0", title: "Atelier de fab : l'ordre des étapes se change", text: "Une étape se glisse à une autre place, ou monte et descend par ses flèches : l'ordre est gardé avec la pièce (la gamme, ses documents et son diaporama le suivent) et le guide dit ce qu'il dérange — un ébavurage avant la fin de l'usinage, un traitement de surface que la suite rayerait, un contrôle trop tôt.", where: "#/fab", sel: ".fab-step", how: "Mécanique › Atelier de fab, la liste « La gamme, étape par étape »." },
  { id: "fab-share", v: "0.145.0", title: "Atelier de fab : diaporama et film pour le fournisseur", text: "Le diaporama (.pptx) : une diapositive par étape, son image, ses opérations, ses mesures et une case où le fournisseur écrit sa réponse ; le film (.webm) : les étapes filmées, leur titre incrusté. La réponse du fournisseur se garde aussi, phase par phase, dans la marge de droite.", where: "#/fab", sel: ".fab-flow", how: "Mécanique › Atelier de fab, « Partager avec le fournisseur »." },
  { id: "door-boards", v: "0.144.0", title: "Créer avec l'IA : cartes et feuilles de dessin dans la réponse", text: "La porte « Avec l'IA » de l'Atelier lit aussi des cartes (rangées dans Électronique ▸ PCBA) et des feuilles de dessin (Mécanique ▸ Dessins), relues comme le bouton « IA » de leur écran les relit — une feuille peut appartenir à une pièce que la même réponse crée. Une seule étape, un seul journal.", where: "#/shop/ai", sel: "[data-door]", how: "Mécanique › Atelier, porte « Avec l'IA »." },
  { id: "journal-all", v: "0.144.0", title: "Flex, étiquettes, photo, Labo : leur réponse d'IA entre au journal", text: "Les écrans qui ont leur propre réimport d'une IA — circuit flexible, circuit ramifié, étiquettes, séance photo, Labo — marquent maintenant ce qu'ils changent comme la boucle commune : « Brouillon IA » à la revue, une entrée au journal que « Revenir à avant » défait, même après d'autres changements.", where: "#/shop/ai", sel: "[data-door]", how: "Le journal se lit sur la page « Créer avec l'IA » et dans la boîte « IA » de chaque écran." },
  { id: "first-board", v: "0.143.0", title: "PCBA et Labo : la première carte, en exemple", text: "La carte la plus simple : une pile bouton, deux boutons, une DEL rouge et une DEL jaune — chaque bouton allume sa DEL, rien à programmer. Deux blocs nés pour elle, « Pile » et « Bouton et témoin », chacun avec ses essais ; un essai de la carte entière sur sa pile, tous les boutons à la fois.", where: "#/pcba", sel: "[data-first-example]", how: "Électronique › PCBA, « Exemple : première carte » (ou dans le Labo, quand le projet n'a pas de carte)." },
  { id: "lab-hand", v: "0.143.0", title: "Manipulation en labo : mettre la pile, appuyer, relâcher", text: "Une étape nouvelle, « Geste à la main » : appuyer sur le bouton montré sur la carte et le tenir pendant les relevés, puis le relâcher ; sur une carte qui vit sur sa pile, la pile se met en place APRÈS la recherche de court-circuit, et se retire à la fin. Un relevé fait au repos passe avant l'appui.", where: "#/elab", sel: ".lab-view", how: "Électronique › Labo, la première carte, un essai, puis « Manipulation en labo »." },
  { id: "draw-uos", v: "0.142.0", title: "Dessins : le bloc « UNLESS OTHERWISE SPECIFIED »", text: "À gauche du cartouche, le bloc de tolérances générales à l'usage nord-américain : unité, tolérance d'une cote selon son nombre de décimales, angles, norme de lecture — ou ISO 2768 au choix du projet. Un seul bloc pour tous les dessins du projet ; les valeurs proposées sont des exemples qui clignotent dans la marge de droite et que la feuille dit « EXAMPLE » jusqu'à ce que vous les entriez ou les confirmiez.", where: "#/drawings", sel: ".uos-block", how: "Mécanique › Dessins, une pièce, marge de droite : « Tolérances générales »." },
  { id: "draw-fcf", v: "0.142.0", title: "Dessins : de vrais cadres GD&T sur la feuille", text: "Plus de drapeaux T1, T2… ni de tableau : chaque tolérance de position, de planéité ou de profil est un cadre posé sur la feuille, sa ligne de repère sur la feature qu'elle contrôle, « 4X » et les repères des trous au-dessus. L'outil le pose là où la feuille est blanche, au plus près ; une découpe rectangulaire est tenue par le profil de sa surface par rapport à A, B et C.", where: "#/drawings", sel: ".sheet-view", how: "Mécanique › Dessins, une pièce qui a des interfaces." },
  { id: "draw-detail", v: "0.142.0", title: "Dessins : une vue de détail d'un cercle tracé sur la feuille", text: "« Choisir une zone », puis sur une vue : appuyez au centre, glissez jusqu'au rayon, relâchez — la zone devient DETAIL D, agrandie à une échelle normalisée, son cercle et sa lettre sur la vue d'origine. Les vues se replacent seules : à l'étroit, elles descendent d'une échelle ; sinon le détail passe sur une feuille à part. Chaque détail a son échelle, On / Off, sa copie (née à Off).", where: "#/drawings", sel: ".detail-pick", how: "Mécanique › Dessins, une pièce, marge de droite : « Vues de détail »." },
  { id: "draw-texts", v: "0.142.0", title: "Dessins : les textes de la feuille, dans la marge de droite", text: "Le titre (le nom de la pièce), la date, la finition s'ajoutent au cartouche éditable ; chaque note générale que l'outil écrit se met à Off pour le projet, vos notes restent dessous. Le bouton « IA » confie aussi le bloc de tolérances, les notes à Off et les vues de détail — une réponse ne confirme jamais les valeurs du bloc.", where: "#/drawings", sel: ".auto-note", how: "Mécanique › Dessins, marge de droite : « Cartouche » et « Notes »." },
  { id: "ai-drawing", v: "0.141.0", title: "Dessins : le bouton « IA » confie la feuille de dessin", text: "Sur l'écran Dessins, « IA » confie la feuille elle-même : le cartouche du projet, l'anglais de chaque texte que le dessin écrit (les vides à remplir), la coupe, les classes de cotes (SC, CSC, REF) et les notes. La réponse est vérifiée, montrée changement par changement, appliquée en une étape annulable et gardée au journal.", where: "#/drawings", sel: ".head-ai", how: "Mécanique › Dessins, une pièce ou un assemblage, puis « IA » en tête du volet de gauche." },
  { id: "ai-case", v: "0.141.0", title: "Simulation : le bouton « IA » confie le cas de charge", text: "Sur l'écran Simulation, « IA » confie le cas de charge de la pièce — le cas en cours et les autres, par leur nom : appuis, efforts, puissances, convection, zones, instruments. Une réponse appliquée remet l'écran à jour ; le journal la défait.", where: "#/fea", sel: ".head-ai", how: "Mécanique › Simulation, une pièce, puis « IA » en tête du volet de gauche." },
  { id: "ai-iso", v: "0.141.0", title: "Isolation : le bouton « IA » confie les réglages d'isolation", text: "Sur l'écran Isolation, « IA » confie les réglages : potentiels et tensions, degré de pollution, altitude, catégorie de surtension, niveau d'isolation de chaque paire, rôles des corps. Les résultats de la dernière analyse sont retirés quand les réglages changent : on relance « Analyser ».", where: "#/creepage", sel: ".head-ai", how: "Électronique › Isolation, un assemblage ou une carte, puis « IA » en tête du volet de gauche." },
  { id: "bm-crimp", v: "0.140.0", title: "BM 8s8p : la couronne HV sertie sous sa rondelle de butée", text: "La butée d'un contact HV devient une rondelle de cuivre à part : sa lèvre tient l'anneau extérieur de la couronne contre la jambe — ni soudure à travers l'argent, ni chaleur sur le cuivre-béryllium ; elle porte la jambe du CORE voisin. Le noyau 3D vérifie que la couronne est prise et que rien ne se traverse.", where: "#/home", sel: "[data-example='bm']", how: "Accueil, « Exemples », carte « BM 8s8p - 21700 » (un nouveau projet), puis la pièce « Rondelle de butée HV » ou l'assemblage « CORE 1S8P »." },
  { id: "bm-hv-elastic", v: "0.139.0", title: "BM 8s8p : le contact HV reste élastique jusqu'à la butée", text: "Des lames plus longues dans la même tôle et moins de course : la butée fixe l'écart, la lame n'absorbe que ± 0,05 mm et reste élastique au pire des cotes ; la couronne plastique de la version d'avant reste en variante de la pièce, et son calcul à côté, pour comparer (effort, résistance, déformation permanente). Le retour DFM sur l'estampage est dans les notes et dans la doc du projet.", where: "#/home", sel: "[data-example='bm']", how: "Accueil, « Exemples », carte « BM 8s8p - 21700 » (un nouveau projet), puis la pièce « Ressort de contact HV », menu des variantes ; ou Calculs › Modèles analytiques, les deux calculs « Contact HV » gardés." },
  { id: "laser-mark", v: "0.139.0", title: "Marquage laser : un texte gravé dans une face", text: "Une nouvelle opération du langage de pièce, « mark » : un texte gravé avec la police à un trait de l'outil, lisible de l'extérieur de la face. Le busbar laminé du CORE en porte huit — HV1 +, HV2 +, RS485 A, RS485 B, et leurs pendants côté −, à côté de chaque contact.", where: "#/home", sel: "[data-example='bm']", how: "Accueil, « Exemples », carte « BM 8s8p - 21700 », puis la pièce « Busbar laminé du CORE » : les jambes ±Y, autour des contacts." },
  { id: "spring-tol", v: "0.139.0", title: "Contact à lames : une tolérance sur la course", text: "Le modèle prend une tolérance ± sur la course jusqu'à la butée : l'effort minimal se vérifie à la course la plus courte, l'élasticité à la plus longue — aussi dans le classeur Excel.", where: "#/physics", sel: "[data-model='spring_stop']", how: "Calculs › Modèles analytiques, groupe « Assemblages », tuile « Spring contact · to its stop », champ « Tolérance sur la course »." },
  { id: "spring-stop", v: "0.138.0", title: "Calculs : un contact à lames pressé jusqu'à sa butée", text: "Un nouveau modèle analytique (Assemblages) : une couronne de lames-ponts écrasée jusqu'à sa butée — l'effort par lame, la course élastique, la déformation permanente quand la lame passe en plastique, la résistance de contact de Holm et le courant qu'un point supporte ; la courbe au-delà de l'élastique est un choix de l'outil, et l'écran le dit.", where: "#/physics", sel: "[data-model='spring_stop']", how: "Calculs › Modèles analytiques, groupe « Assemblages », tuile « Spring contact · to its stop »." },
  { id: "bm-contacts", v: "0.138.0", title: "BM 8s8p : les 4 contacts entre deux CORE, pressés jusqu'aux butées", text: "Sur la jambe + de chaque CORE, deux ressorts HV et deux ressorts LV (RS-485 A et B) en couronne de lames de cuivre-béryllium, entourés de leurs butées ; sur la jambe −, des plages planes ; un cercle gravé au laser autour de chaque contact ; les plages LV sont des îlots isolés. Deux CORE sont à 0,35 mm, sur leurs butées ; le calcul de chaque contact est gardé dans le projet.", where: "#/home", sel: "[data-example='bm']", how: "Accueil, « Exemples », carte « BM 8s8p - 21700 » (un nouveau projet), puis les pièces « Ressort de contact HV » et « Busbar laminé du CORE », ou l'assemblage « CORE 1S8P »." },
  { id: "flat-view", v: "0.137.0", title: "Une pièce mince pliée, vue à plat avec ses lignes de pli", text: "Dans la barre de la vue, « Plié · À plat » déplie un flex, une bande flexible, un busbar ou une tôle pliée : le flan vu du dessus, chaque pli tracé avec sa note (UP / DOWN, angle, rayon intérieur), les sondes et les prises à leur place ; « Plié » revient à la pièce montée.", where: "#/flex", sel: "[data-flat-toggle]", how: "Ouvrir une pièce pliée — le flex en boîte du projet « BM 8s8p - 21700 », par exemple — puis « À plat » dans la barre de la vue." },
  { id: "bm-iter5", v: "0.136.0", title: "BM 8s8p : le support du bas et ses rondelles, en une pièce", text: "Le support du bas a un fond sous les cellules, qui isole les godets de la plaque − et laisse monter les soudures par ses fenêtres ; ses 8 rondelles thermiques y sont moulées en deuxième injection (2K) et descendent jusqu'aux CTN du flex.", where: "#/home", sel: "[data-example='bm']", how: "Accueil, « Exemples », carte « BM 8s8p - 21700 » (un nouveau projet ; celui d'avant reste tel quel), puis la pièce « Support du bas des cellules, avec ses rondelles »." },
  { id: "bm-iter4", v: "0.135.0", title: "BM 8s8p : busbar laminé, flex en boîte, une CTN sous chaque cellule", text: "Les deux L d'un CORE en un seul busbar laminé (papier aramide côté cellules, film dehors, une fenêtre par calotte +) ; le flex livré à plat se replie en boîte autour du CORE jusqu'à poser la carte sur le dessus ; une CTN sous le centre de chaque cellule, par le trou de la plaque − et sa rondelle thermique.", where: "#/home", sel: "[data-example='bm']", how: "Accueil, « Exemples », carte « BM 8s8p - 21700 » (un nouveau projet ; celui d'avant reste tel quel)." },
  { id: "bm-holder", v: "0.134.0", title: "BM 8s8p : le support de cellules du CORE", text: "Une pièce moulée, deux par CORE (en haut et en bas) : une épine entre les rangées et ses dents, une barre à chaque petit bout qui laisse au flex son passage, une poche de 21,8 mm autour de chaque cellule, des noyautages qui gardent des parois moulables (aucune erreur au bilan DFx) ; le noyau 3D vérifie qu'elle ne touche rien.", where: "#/home", sel: "[data-example='bm']", how: "Accueil, « Exemples », carte « BM 8s8p - 21700 » (un nouveau projet ; celui d'avant reste tel quel), puis la pièce « Support de cellules du CORE »." },
  { id: "bm-iter2", v: "0.133.0", title: "BM 8s8p : cuivre dimensionné à 360 A, flex plié en G", text: "La cellule est la Molicel P45B de sa fiche : 45 A en décharge continue, × 8 = 360 A par CORE ; les busbars passent à 2,0 mm (calcul gardé dans le projet, sous 60 °C et 2,5 A/mm²) et laissent les jeux de 3 mm au flex ; le flex en G plonge par les petits bouts, 4 doigts par bout, une CTN sous chaque cellule, B+ et B−.", where: "#/home", sel: "[data-example='bm']", how: "Accueil, « Exemples », carte « BM 8s8p - 21700 » (un nouveau projet ; celui d'avant reste tel quel)." },
  { id: "cell-p45b", v: "0.133.0", title: "Bibliothèque : la cellule Molicel P45B, de sa fiche", text: "Une cellule 21700 d'un fabricant, ses valeurs lues page par page : dimensions, 45 A en décharge et 9 A en charge continues, températures admissibles — la fiche et ses pages dites sur la pièce.", where: "#/library", sel: "[data-cell='21700-P45B']", how: "Bibliothèque, « Cellules Li-ion cylindriques »." },
  { id: "bm-project", v: "0.132.0", title: "Accueil : le projet « BM 8s8p - 21700 »", text: "Le module de batterie en exemple, à itérer : 8 CORE de 8 cellules 21700 en parallèle, en série côte à côte ; chaque CORE avec sa carte de mesure dessus, son busbar + et son busbar − dont les jambes se pressent d'un CORE au suivant, et ses isolants de flanc. Les épaisseurs sont des exemples.", where: "#/home", sel: "[data-example='bm']", how: "Accueil, « Exemples », carte « BM 8s8p - 21700 »." },
  { id: "hist-main", v: "0.131.0", title: "Historique : MAIN au centre, les branches à côté", text: "Chaque point a sa branche ; MAIN, la branche principale, est au milieu de l'arbre, plus épaisse et nommée en tête ; les autres s'ouvrent de chaque côté, leur nom sur leur dernier point. Revenir au milieu d'une branche et continuer en ouvre une nouvelle, que l'on nomme.", where: "#/history", sel: "[data-lane]", how: "Produit › Historique, au centre." },
  { id: "hist-merge", v: "0.131.0", title: "Historique : fusionner une branche dans MAIN, d'un bloc", text: "L'aperçu dit ce qui vient de la branche, ce que MAIN perd, ce qu'il garde, et les pièces qui reviennent à Off, grisées, à activer pour les replacer ; puis une étape annulable et un point de fusion sur MAIN.", where: "#/history", sel: "[data-history-branches]", how: "Produit › Historique, volet de gauche, « Les branches »." },
  { id: "hist-team", v: "0.131.0", title: "Historique : le travail d'un coéquipier devient une branche", text: "« Lire le travail d'un coéquipier » prend son fichier de projet et l'ajoute comme une branche, partie du point que vos deux fichiers partagent ; « vous êtes ici » ne bouge pas.", where: "#/history", sel: "[data-history-import]", how: "Produit › Historique, volet de gauche, sous « Les branches »." },
  { id: "core-board", v: "0.130.0", title: "PCBA : la carte de CORE, en exemple", text: "Une petite carte de la taille du dessus d'un CORE de 8 cellules 21700 : les 8 CTN sur les rabats d'un flex joint sous la carte, la tension du CORE, l'équilibrage passif, RS-485 isolé dont le côté bus est alimenté par le faisceau — routée, contrôles sans erreur. Les composants sont génériques.", where: "#/pcba", sel: "[data-core-example]", how: "Électronique › PCBA, « Exemple : carte de CORE »." },
  { id: "kernel-restart", v: "0.130.0", title: "Pièces : un noyau 3D calé se relance seul", text: "Quand toutes les opérations d'une pièce échouent d'un coup, l'outil vérifie que le noyau 3D sait encore faire un cube ; sinon il le relance et reconstruit la pièce. La première erreur se lit sous le pointeur, sur la pastille de la pièce.", where: "#/parts", sel: "[data-build-info]", how: "Mécanique › Pièces : la pastille de la pièce, sous la vue." },
  { id: "sw-docs", v: "0.129.0", title: "Logiciel : spécification et rapport de vérification", text: "Les deux documents avec lesquels un logiciel part : ce qu'il doit faire (chaque exigence, sa preuve, ses tuiles, la trace jusqu'aux fichiers C) et ce qui a été prouvé (chaque essai sur le modèle, ses attendus, la matrice, la couverture du modèle, la liste de livraison) — au gabarit des documents. Le paquet C en porte la même matière : doc/REQUIREMENTS.md, doc/VERIFICATION.md.", where: "#/swrel", sel: "[data-sw-docs]", how: "Logiciel › 7. Livraison, « Les documents du logiciel » ; aussi en tête des étapes 1 et 6." },
  { id: "sw-docs-req", v: "0.129.0", title: "Exigences : la spécification d'un clic", text: "En tête du volet des Exigences : la spécification des exigences du logiciel, en Word ou en PDF.", where: "#/swreq", sel: "[data-sw-docs]", how: "Logiciel › 1. Exigences." },
  { id: "sw-docs-test", v: "0.129.0", title: "Vérification : le rapport d'un clic", text: "En tête du volet de la Vérification : le rapport de vérification, les essais rejoués sur le modèle au moment où il s'écrit.", where: "#/swtest", sel: "[data-sw-docs]", how: "Logiciel › 6. Vérification." },
  { id: "sw-group", v: "0.128.0", title: "Logiciel : un groupe à part, en cycle en V", text: "Le logiciel quitte l'Électronique : un groupe « Logiciel » dans la barre du haut, sept écrans dans l'ordre du cycle en V — Exigences, Architecture, Conception, Simulation, Code, Vérification, Livraison. Le V est dessiné au-dessus de chaque écran, chaque étape dit où elle en est ; les étapes faites l'une pour l'autre sont reliées en pointillé.", where: "#/swreq", sel: "[data-sw-v]", how: "Logiciel, dans la barre du haut." },
  { id: "sw-req", v: "0.128.0", title: "Exigences : une phrase avec « doit », relue, allouée, tracée", text: "Chaque exigence a son genre (fonction, sécurité, performance, interface, robustesse), sa preuve (essai, analyse, revue) et les tuiles qui la réalisent. L'outil relit la phrase (mot vague, pas de nombre) ; la carte de traçabilité relie exigences, tuiles et essais, et montre une tuile que personne n'a demandée.", where: "#/swreq", sel: "[data-sw-trace]", how: "Logiciel › 1. Exigences." },
  { id: "sw-std", v: "0.128.0", title: "Référence de sécurité au choix du projet : DO-178C ou ISO 26262", text: "L'Architecture fait choisir la référence et le niveau (DAL A à E, ou ASIL QM, A à D) ; ce que le niveau demande est dit en quelques lignes, d'après des pages publiques lues — les normes elles-mêmes ne l'ont pas été, et l'écran le dit.", where: "#/swarch", sel: "[data-sw-std-ref]", how: "Logiciel › 2. Architecture." },
  { id: "sw-test", v: "0.128.0", title: "Vérification : des essais sur le modèle, la matrice et la couverture", text: "Un essai est un scénario — ce que lit chaque broche, en mV quand elle mesure une tension — et ce que l'on attend : une valeur à un instant, ou un changement dans une fenêtre. La matrice dit quelle exigence est prouvée ; la liste dit quelle décision les essais n'ont jamais fait basculer.", where: "#/swtest", sel: "[data-sw-matrix]", how: "Logiciel › 6. Vérification, « Lancer les essais »." },
  { id: "sw-release", v: "0.128.0", title: "Livraison : ce qui doit tenir avant que le paquet parte", text: "La liste de livraison — référence choisie, exigences confirmées et allouées, valeurs relues, essais réussis, preuves signées — dit pour chaque ligne l'étape où la régler, au-dessus du paquet et des sept gestes du chargement.", where: "#/swrel", sel: "[data-sw-release]", how: "Logiciel › 7. Livraison." },
  { id: "eco", v: "0.127.0", title: "Écosystème : tout le produit pour une IA, en un paquet", text: "La carte de ce qui dépend de quoi — l'artéfact confié entouré, ce qu'il dérange en ambre —, une entrevue (ce que je veux, ce qui ne doit pas bouger, comment je saurai que c'est réussi), le cadre de conception — les règles que l'outil vérifie et celles du projet, On / Off — et un paquet .zip avec la consigne.", where: "#/eco", sel: "[data-eco-map]", how: "Produit › Écosystème, ou « Tout le contexte » dans la boîte IA de chaque écran." },
  { id: "history", v: "0.126.0", title: "Historique : points de restauration et arbre des branches", text: "Un point garde TOUT le produit à un moment — pièces, assemblages, cartes, logiciel, revues, révisions —, chaque artéfact rangé une seule fois. Revenir à un point (une étape annulable), comparer deux points, repartir : une branche s'ouvre. Un point se pose aussi tout seul après une réponse d'IA appliquée.", where: "#/history", sel: "[data-history-tree], .hist-empty", how: "Produit › Historique, ou menu Projet › Historique." },
  { id: "view-bar", v: "0.125.0", title: "Une barre de zoom sur chaque vue, avec la loupe", text: "En haut à droite des tuiles du logiciel, d'une carte (PCBA, Labo) et d'un dessin : − et +, le pourcentage (taille réelle), « Ajuster » (tout se voit) et la loupe. Les tuiles se zooment à la molette et se déplacent en glissant le fond. La loupe a quitté la barre du haut.", where: "#/sw", sel: "[data-view-bar]", how: "Électronique › Logiciel, ou une carte, ou un dessin." },
  { id: "bottom-pane", v: "0.125.0", title: "Le panneau du bas se grandit et se replie", text: "Sous la simulation du Logiciel et sous les oscilloscopes du Labo : glissez la bordure du haut pour le grandir, son bouton ▾ le replie. La hauteur est gardée pour chaque écran.", where: "#/sw/live", sel: ".hsplit", how: "Logiciel, étape 5 « Simulation » ; ou le Labo d'une carte." },
  { id: "sw-steps", v: "0.124.0", title: "Logiciel : sept étapes, dites pour quelqu'un qui apprend", text: "En tête du volet de gauche : CPU, objets, valeurs, démarrage, simulation, code, chargement. Chaque étape dit en clair ce qu'elle est et ce que l'on fait, si elle est faite, et déplie ses mots du métier ; le guide est sous elle. Chaque tuile dit ses ENTRÉES et ses SORTIES.", where: "#/sw", sel: "[data-sw-step]", how: "Logiciel › 3. Conception, puis « Partir de l'exemple »." },
  { id: "sw-live", v: "0.124.0", title: "Une simulation en direct, en pause ou en marche", text: "À l'étape 5, le logiciel tourne devant vous : vous tenez le banc — la tension d'une cellule, la demande de fermeture, un contact coincé ou soudé — et les tuiles réagissent. Pause, un pas, marche, vitesse ; un chronogramme et le journal de ce qui a basculé.", where: "#/sw/live", sel: "[data-sw-bench]", how: "Logiciel, étape 5 « Simulation »." },
  { id: "sw-load", v: "0.124.0", title: "Le code se lit à l'écran, et l'on sait comment le charger", text: "À l'étape 6, chaque fichier du paquet s'ouvre au centre, avec ses numéros de ligne. À l'étape 7, les sept gestes du paquet au CPU, avec ce que le fabricant publie et la page où cela a été lu ; l'étape 4 essaie le démarrage et compte la mémoire.", where: "#/sw/load", sel: "[data-sw-load]", how: "Logiciel, étapes 4, 6 et 7." },
  { id: "panes-all", v: "0.123.0", title: "Marges à cacher et à redimensionner, sur toutes les pages", text: "Le PCBA n'avait aucune bordure à glisser, le Logiciel aucune à droite : toute page qui a un volet de gauche ou de droite en a maintenant. Glisser la bordure élargit le volet, son bouton le cache ; la largeur est la même d'un écran à l'autre.", where: "#/pcba", sel: ".split", how: "La bordure entre un volet et le centre ; Ctrl + B pour le volet de gauche." },
  { id: "access-clear", v: "0.123.0", title: "Accès à la démo : les comptes et leurs droits, en clair", text: "Une ligne par compte : un nom que vous lui donnez (gardé dans ce navigateur seulement), son rôle et ce qu'il permet, et s'il est publié ou encore à publier. Ce qu'il reste à faire est dit pas à pas ; ce que vous ajoutez est gardé d'une visite à l'autre.", where: "#/account", sel: "[data-access-row]", how: "Menu du compte › Compte, Drive et accès — pour l'administrateur." },
  { id: "iso-board", v: "0.122.0", title: "Isolation : une carte seule, ou un assemblage", text: "Le menu « Ce que l'on analyse » offre les cartes (PCBA) à côté des assemblages. Une carte s'analyse seule, sur son cuivre réel — pastilles, pistes, vias —, ses nets regroupés par tension ; chaque paire nomme ses deux nets les plus proches.", where: "#/creepage", sel: "[data-iso-subject]", how: "Électronique › Isolation, ou la marche « Isolation » en tête du volet du PCBA." },
  { id: "sw-objects", v: "0.121.0", title: "Logiciel : des objets reliés, dont l'outil écrit le C", text: "Un nouvel écran : le logiciel embarqué d'un BMS se dessine en tuiles reliées par des fils — mesurer, décider, commander. L'outil en écrit le C (bibliothèque, modules, structure de fichiers) pour le CPU choisi, avec l'essai qui le compare au dessin.", where: "#/sw", sel: "[data-sw-zip]", how: "Électronique › Logiciel, puis « Partir de l'exemple »." },
  { id: "variant-live", v: "0.120.0", title: "L'arbre dit de quelle variante il est", text: "La variante en cours est vivante : une opération mise à On ou à Off, un paramètre changé lui appartient, sans bouton à presser. Son nom est sur le titre de l'arbre et des paramètres ; le premier « + » garde aussi la pièce d'avant, sous « Origine ».", where: "#/parts", sel: "[data-variant-on]", how: "Visible sur une pièce qui a au moins une variante (le « + » du groupe « Variantes »)." },
  { id: "lab-plain", v: "0.119.0", title: "Chaque étape du banc, dite en clair", text: "Sous son titre, chaque étape de « Manipulation en labo » dit en une ou deux phrases ce que l'on fait, avec l'image de l'eau quand elle aide ; les mots du banc qu'elle emploie se déplient dessous, et chaque point dit ce qu'est son signal.", where: "#/elab", sel: "[data-manip-plain]", how: "Labo, bouton « Manipulation en labo »." },
  { id: "lab-bench", v: "0.119.0", title: "L'écran et le vrai banc : ce qui change, et pourquoi", text: "Sous les courbes, le Labo dit comment l'essai se fait au vrai banc. Un essai au multimètre relève maintenant la fin de chaque courbe (l'anneau blanc) ; un temps demande un oscilloscope et n'est plus dû. La fiche a son groupe « L'écran et le vrai banc ».", where: "#/elab", sel: "[data-bench-note]" },
  { id: "rev-freeze", v: "0.118.0", title: "Geler la révision — et voir son état d'un coup d'œil", text: "« Libérer… » se dit maintenant « Geler la révision » : le contenu est figé sous son numéro, et l'on nomme son auteur. Chaque ligne porte le nom de la révision et son état — en travail, gelée, libérée, refusée.", where: "#/plm", sel: "[data-rev-freeze]" },
  { id: "rev-review", v: "0.118.0", title: "La revue de conception qui libère une révision gelée", text: "Une liste courte : ce que l'outil vérifie lui-même sur le contenu gelé, puis ce que l'approbateur — quelqu'un d'autre que l'auteur — confirme. Il écrit la décision et les points ouverts ; la fiche de revue sort en PDF.", where: "#/plm", sel: "[data-rev-review]", how: "Visible sur une révision gelée, en attente de sa revue." },
  { id: "lab-manip-pdf", v: "0.117.0", title: "La manipulation sur papier, une image par étape", text: "Dans « Manipulation en labo » : « PDF » sort la procédure de l'essai avec une image de la carte à chaque étape qui la touche, une case par relevé et des lignes de notes ; remplie de ce qui est déjà coché, relevé et noté, c'est le compte rendu. « Tout le plan » fait le même cahier pour tous les essais.", where: "#/elab", sel: "[data-manip-pdf]", how: "Labo, bouton « Manipulation en labo », en haut de l'écran qui s'ouvre." },
  { id: "battery-words", v: "0.116.0", title: "Le vocabulaire des batteries, tel que publié", text: "Chaque terme d'un système de batterie avec la norme ou le texte d'autorité qui le porte, et comment il a été lu ; les mots de maison — CMB, BMU, BM, EFC — avec ce qui a été trouvé ; ce que les documents publics disent des bus.", where: "#/help/batteries", sel: ".battery-card" },
  { id: "rs485-example", v: "0.116.0", title: "Un exemple complet : le nœud RS-485", text: "Une carte d'exemple où toute la liaison est posée — bornier, écrêteur et résistances série, terminaison, polarisation, transceiver, trois broches du microcontrôleur — avec ses pistes, ses essais du Labo (niveaux, bus au repos, une trame) et son pilote.", where: "#/pcba", sel: '[data-example="rs485"]' },
  { id: "hwsw-sheet", v: "0.116.0", title: "L'interface matériel / logiciel d'une liaison", text: "Lue des nets de la carte : quelle broche du microcontrôleur porte quel signal, sous quel nom le logiciel le connaît, les temps à tenir. La fiche sort en Word ou en PDF, et le pilote C — écrit à partir du même modèle — en .zip.", where: "#/pcba", sel: "[data-hwsw]", how: "PCBA d'une carte qui porte un bloc RS-485, étape « Revue »." },
  { id: "lab-manip", v: "0.115.0", title: "Manipulation en labo : l'essai fait au vrai banc", text: "L'essai choisi, une étape par écran, en plein écran : chaque branchement est pointé sur la carte, l'appareil est dessiné avec son réglage, une étape s'ouvre quand celles d'avant sont faites, un relevé hors plage arrête l'essai. Relevés et notes restent dans le carnet de la carte.", where: "#/elab", sel: "[data-manip]" },
  { id: "news-marks", v: "0.114.0", title: "Ce qui est nouveau est marqué à l'écran", text: "Chaque nouveauté d'une version porte une marque sur l'élément lui-même. Ce bouton en ouvre la liste : « Montrer » y mène, « vu » la coche — la marque reste, pour la trace — et « Passer à une nouvelle revue » les range.", sel: "#news-btn", how: "Barre du haut, le bouton à l'étoile." },
  { id: "sim-chip", v: "0.113.0", title: "Simuler la géométrie d'un calcul à la main", text: "Sous le schéma d'un modèle analytique : ouvre la Simulation sur un modèle simplifié fait du calcul — mêmes dimensions, même matière, mêmes appuis, même charge.", where: "#/physics/beam_cantilever_point", sel: ".sim-chip" },
  { id: "study-up", v: "0.113.0", title: "Du modèle simplifié, remonter au calcul", text: "Dans la Simulation d'un modèle simplifié, la marche vers le haut ramène au modèle analytique, avec ses valeurs. L'Atelier range ces modèles en dernier, sous « Simplified models ».", where: "#/shop", sel: '[data-part^="MS-"]', how: "Visible une fois qu'un modèle a été simulé." },
  { id: "stair-down", v: "0.112.0", title: "Descendre d'un niveau", text: "À côté de la marche vers le haut : les pictogrammes de ce qui est fait à partir de ce que l'écran montre — la carte mène à son PCBA, le PCBA à son Labo, une pièce à son dessin et à sa simulation. Alt + ↓.", where: "#/parts", sel: ".stair-downs" },
  { id: "twin-note", v: "0.112.0", title: "La carte dit de quel PCBA elle vient", text: "Le jumeau mécanique naît au premier composant placé et suit le PCBA à chaque changement ; la carte y mène d'un clic.", where: "#/pcb", sel: "[data-twin-of]", how: "Visible sur une carte qui porte un PCBA." },
  { id: "board-names", v: "0.112.0", title: "Noms du métier : PCB · PCBA, PWB · CCA, ou vos mots", text: "Tout l'écran et les documents Word et PDF suivent ; les identifiants et les fichiers ne changent pas.", sel: ".board-names", how: "Menu du compte (le bonhomme, en haut à droite)." },
  { id: "val-chip", v: "0.111.0", title: "Un calcul rejoué contre un exemple publié", text: "Sous le schéma d'un modèle : combien d'exemples publiés il retrouve. Un clic ouvre le groupe « Validation » — la source, ce qu'elle imprime, ce que l'outil trouve, l'écart.", where: "#/physics/beam_cantilever_point", sel: ".val-chip" },
  { id: "val-fea", v: "0.111.0", title: "La validation du solveur de la Simulation", text: "Dans le volet de droite : les exemples publiés que le solveur rejoue, dans la page, sur un maillage dit.", where: "#/fea", sel: ".side.right .val-section" },
  { id: "val-help", v: "0.111.0", title: "Le tableau d'ensemble de la validation", text: "Chaque modèle et chaque famille de la simulation, avec ses cas — ou la phrase qui dit qu'il n'en a pas.", where: "#/help/validation", sel: ".val-card" },
  { id: "head-ai", v: "0.110.0", title: "Le bouton « IA » de chaque studio", text: "En tête du volet de gauche : confie à un assistant ce que l'écran montre ; toute réponse appliquée entre au journal.", where: "#/parts", sel: ".head-ai" },
];
/** How many versions back a first review reaches, when nobody opened one yet. */
export const FIRST_SPAN = 4;
const minor = (v) => parseVersion(v)[1] || 0;
/** The base of a first review : a few versions back. « 0.114.0 » → « 0.110.0 ». */
export const firstBase = (running) => { const p = parseVersion(running); return `${p[0] || 0}.${Math.max(0, (p[1] || 0) - FIRST_SPAN)}.0`; };
/** The review in force, tidied. → { base, seen: { id: date }, before: { base, seen, closed } | null } */
export function tidyReview(raw, running) {
  const ok = (v) => typeof v === "string" && /^\d+\.\d+\.\d+$/.test(v), r = raw && typeof raw === "object" ? raw : {};
  const base = ok(r.base) && !newer(r.base, running) ? r.base : firstBase(running), seen = {};
  for (const [k, d] of Object.entries(r.seen && typeof r.seen === "object" ? r.seen : {})) if (NEWS.some((n) => n.id === k)) seen[k] = String(d);
  const b = r.before && ok(r.before.base) ? { base: r.before.base, seen: { ...(r.before.seen || {}) }, closed: String(r.before.closed || "") } : null;
  return { base, seen, before: b };
}
/** The lines of a review : what was published after its base, up to the running version. → [{ ...line, seen (date or "") }] newest first */
export function reviewLines(review, running) {
  return NEWS.filter((n) => newer(n.v, review.base) && !newer(n.v, running)).map((n) => ({ ...n, seen: review.seen[n.id] || "" }));
}
/** The lines by version : → [{ v, lines }] */
export function byVersion(lines) { const out = []; for (const n of lines) { let g = out.find((x) => x.v === n.v); if (!g) out.push(g = { v: n.v, lines: [] }); g.lines.push(n); } return out.sort((a, b) => minor(b.v) - minor(a.v)); }
/** Where a review stands : → { total, seen, left, text } */
export function reviewCount(lines) { const seen = lines.filter((n) => n.seen).length; return { total: lines.length, seen, left: lines.length - seen, text: !lines.length ? "Aucune nouveauté à revoir" : `${seen} vue${seen > 1 ? "s" : ""} sur ${lines.length}` }; }
/** A line ticked, or unticked : → the review */
export function markSeen(review, id, on = true, when = new Date().toISOString()) { const seen = { ...review.seen }; if (on) seen[id] = seen[id] || when; else delete seen[id]; return { ...review, seen }; }
/** A new review : the marks of this one are put away — kept as the review before — and the base becomes the running version. */
export function nextReview(review, running, when = new Date().toISOString()) { return { base: running, seen: {}, before: { base: review.base, seen: { ...review.seen }, closed: when } }; }
/** Back to the review before : its base and its ticks return. */
export function previousReview(review) { return review.before ? { base: review.before.base, seen: { ...review.before.seen }, before: null } : review; }
/** A line is whole : → [problems] */
export function lineProblems(n) {
  const out = [];
  if (!n.id || !/^[a-z0-9-]+$/.test(n.id)) out.push("identifiant absent ou mal formé");
  if (!/^\d+\.\d+\.\d+$/.test(n.v || "")) out.push("version absente");
  if (!n.title || n.title.length > 70) out.push("titre absent ou trop long"); if (!n.text || n.text.length < 30) out.push("la phrase qui dit ce qui est nouveau manque");
  if (!n.sel) out.push("l'élément de l'écran n'est pas désigné"); if (!n.where && !n.how) out.push("ni écran, ni façon d'y arriver");
  return out;
}

/* ---------- the review, kept in this browser ---------- */
const KEY = "dw.news.review";
let memo = null, memoFor = null;
export function getReview(running) {
  if (memo && memoFor === running) return memo;
  let p = null;
  try { p = typeof localStorage !== "undefined" ? JSON.parse(localStorage.getItem(KEY) || "null") : null; } catch (e) { p = null; }
  memo = tidyReview(p, running); memoFor = running; return memo;
}
export function setReview(review, running) {
  memo = tidyReview(review, running); memoFor = running;
  try { if (typeof localStorage !== "undefined") localStorage.setItem(KEY, JSON.stringify(memo)); } catch (e) { /* private window : the review lasts for this page only */ }
  if (typeof window !== "undefined" && typeof CustomEvent !== "undefined") window.dispatchEvent(new CustomEvent("dw:news", { detail: memo }));
  return memo;
}
